    "q3_title": "Q3. சந்தை விலைக்கும் MSP-க்கும் என்ன வித்தியாசம்?",
    "q3_ans": "MSP என்பது அரசு உத்தரவாதம் அளிக்கும் குறைந்தபட்ச ஆதரவு விலை.",
    "q4_title": "Q4. இந்த அறிக்கைகளை ஆஃப்லைனில் படிக்க முடியுமா?",
    "q4_ans": "ஆம், பெறப்பட்ட அனைத்து அறிக்கைகளும் உங்கள் தொலைபேசியில் பாதுகாப்பாகச் சேமிக்கப்படும்.",
